package codeflow

import codeflow.graph.GraphException
import codeflow.java.AstReader
import com.google.gson.JsonObject
import com.google.gson.JsonParser
import org.w3c.dom.Document
import org.w3c.dom.Element
import java.io.ByteArrayInputStream
import java.nio.file.Files
import java.nio.file.Path
import javax.xml.parsers.DocumentBuilderFactory
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertTrue


class AppTest {

    private val userDirectory = System.getProperty("user.dir")
    private val userDirPath = Path.of(userDirectory)
    private val testResourcesPath = userDirPath
        .resolve("src")
        .resolve("test")
        .resolve("resources")

    private fun buildGraph(testDir: String, testFiles: List<String>): List<String> {
        val testDirPath = testResourcesPath.resolve(testDir)
        val testFilePaths = testFiles.map { testDirPath.resolve(it) }
        val mainMethod = AstReader(testResourcesPath).process(testFilePaths)

        val result = ArrayList<String>()
        MermaidExporter()
            .processMainMethod(mainMethod) { result.add(it) }
        return result
    }

    /**
     * The GraphML rendering, parsed.
     *
     * Parsing with a real XML parser rather than matching text is the point: a label that is XML
     * syntax has to come back out as its own characters, and the document has to be something a
     * viewer can actually open.
     */
    private fun buildGraphml(testDir: String, testFiles: List<String>): Document {
        val testDirPath = testResourcesPath.resolve(testDir)
        val testFilePaths = testFiles.map { testDirPath.resolve(it) }
        val mainMethod = AstReader(testResourcesPath).process(testFilePaths)

        val text = StringBuilder()
        GraphmlExporter()
            .processMainMethod(mainMethod) { text.append(it).append("\n") }
        return DocumentBuilderFactory.newInstance()
            .newDocumentBuilder()
            .parse(ByteArrayInputStream(text.toString().toByteArray()))
    }

    /** The JSON rendering, parsed with a library that did not write it. */
    private fun buildJson(testDir: String, testFiles: List<String>): JsonObject {
        val testDirPath = testResourcesPath.resolve(testDir)
        val testFilePaths = testFiles.map { testDirPath.resolve(it) }
        val mainMethod = AstReader(testResourcesPath).process(testFilePaths)

        val text = StringBuilder()
        JsonExporter().processMainMethod(mainMethod) { text.append(it).append("\n") }
        return JsonParser.parseString(text.toString()).asJsonObject
    }

    private fun jsonNodes(doc: JsonObject) = doc.getAsJsonArray("nodes").map { it.asJsonObject }

    private fun jsonLabel(node: JsonObject) = node.get("label").asString

    private fun jsonParent(node: JsonObject) = node.get("parent")?.asString

    /** The JSON edges as (source label, target label) pairs, to compare against [edgeLabels]. */
    private fun jsonEdgeLabels(doc: JsonObject): List<Pair<String, String>> {
        val labels = jsonNodes(doc).associate { it.get("id").asString to jsonLabel(it) }
        return doc.getAsJsonArray("edges").map { it.asJsonObject }.map {
            (labels[it.get("source").asString] ?: "?") to (labels[it.get("target").asString] ?: "?")
        }
    }

    private fun elements(doc: Document, tag: String): List<Element> {
        val found = doc.getElementsByTagName(tag)
        return (0 until found.length).map { found.item(it) as Element }
    }

    /** A node's own `data`, not that of the nodes nested inside it. */
    private fun dataOf(node: Element, key: String): String? {
        val children = node.childNodes
        return (0 until children.length)
            .mapNotNull { children.item(it) as? Element }
            .firstOrNull { it.tagName == "data" && it.getAttribute("key") == key }
            ?.textContent
    }

    private fun labelOf(node: Element) = dataOf(node, "label") ?: ""

    /** The label of the block this node is nested in, or null for the outermost one. */
    private fun enclosingBlockLabel(node: Element): String? {
        var ancestor = node.parentNode
        while (ancestor != null) {
            if (ancestor is Element && ancestor.tagName == "node") return labelOf(ancestor)
            ancestor = ancestor.parentNode
        }
        return null
    }

    /** The GraphML edges as (source label, target label) pairs, to compare against [edgeLabels]. */
    private fun graphmlEdgeLabels(doc: Document): List<Pair<String, String>> {
        val labels = elements(doc, "node").associate { it.getAttribute("id") to labelOf(it) }
        return elements(doc, "edge").map {
            (labels[it.getAttribute("source")] ?: "?") to (labels[it.getAttribute("target")] ?: "?")
        }
    }

    /** The declared nodes as (label, type) pairs, ignoring the generated ids. */
    private fun nodeTypes(graph: List<String>): List<Pair<String, String>> {
        val declaration = Regex("""^\s*n\d+\[([^]]*)]:::(\w+)$""")
        return graph.mapNotNull { line ->
            declaration.find(line)?.let { it.groupValues[1] to it.groupValues[2] }
        }
    }

    /** The graph's edges as (source label, target label) pairs, ignoring the generated ids. */
    private fun edgeLabels(graph: List<String>): List<Pair<String, String>> {
        val edge = Regex("""n\d+\[([^]]*)]:::\w+ --> n\d+\[([^]]*)]""")
        return graph.mapNotNull { line ->
            edge.find(line)?.let { it.groupValues[1] to it.groupValues[2] }
        }
    }

    /**
     * Whether a value can reach another node by following edges.
     *
     * Labels alone cannot answer this when two distinct variables share a name, which is exactly
     * the case worth testing, so this walks the ids and only uses labels for the two endpoints.
     */
    private fun reaches(graph: List<String>, fromLabel: String, toLabel: String): Boolean {
        val edge = Regex("""(n\d+)\[([^]]*)]:::\w+ --> (n\d+)\[([^]]*)]""")
        val edges = graph.mapNotNull { edge.find(it) }
        val outgoing = edges.groupBy({ it.groupValues[1] }, { it.groupValues[3] })
        val labelOf = HashMap<String, String>()
        edges.forEach {
            labelOf[it.groupValues[1]] = it.groupValues[2]
            labelOf[it.groupValues[3]] = it.groupValues[4]
        }
        val seen = HashSet<String>()
        val queue = ArrayDeque(labelOf.filterValues { it == fromLabel }.keys)
        while (queue.isNotEmpty()) {
            val id = queue.removeFirst()
            if (!seen.add(id)) continue
            if (labelOf[id] == toLabel && seen.size > 1) return true
            outgoing[id]?.forEach { queue.addLast(it) }
        }
        return false
    }

    private fun codeflow(testDir: String, testFiles: List<String>) {
        val testDirPath = testResourcesPath.resolve(testDir)
        val result = buildGraph(testDir, testFiles)

        // The snapshot is only written when it does not exist yet, or when explicitly asked for.
        // Rewriting it on every mismatch would let a regression overwrite the expectation and pass
        // on the next run.
        val truthPath = testDirPath.resolve("truth.md")
        if (!Files.exists(truthPath) || System.getenv("UPDATE_SNAPSHOTS") == "1") {
            Files.write(truthPath, result)
        }
        assertEquals(
            Files.readAllLines(truthPath), result,
            "Graph for '$testDir' does not match truth.md. Re-run with UPDATE_SNAPSHOTS=1 to accept the new output."
        )

        assertNoSelfEdges(testDir, result)
        assertNoUnknownOperators(testDir, result)
        assertNoDuplicateNodeIds(testDir, result)
    }

    /**
     * A node with an edge to itself means two different AST nodes were given the same id and so
     * were merged into one. Nothing in the language produces a value that flows into itself.
     */
    private fun assertNoSelfEdges(testDir: String, graph: List<String>) {
        val edge = Regex("""n(\d+)\[[^]]*]:::\w+ --> n(\d+)\[""")
        val selfEdges = graph.filter { line ->
            val match = edge.find(line)
            match != null && match.groupValues[1] == match.groupValues[2]
        }
        assertTrue(selfEdges.isEmpty(), "Graph for '$testDir' has nodes with an edge to themselves: $selfEdges")
    }

    /**
     * Two nodes rendered under one id are drawn as one box, and every edge of both lands on it, so
     * the diagram claims values flow between things that never touched. Identity used to be a hash
     * of the node's label and call stack, which could always collide; it is now a serial handed out
     * at creation, which cannot. This is here to notice if a derived id is ever reintroduced.
     *
     * Only the declaration lines are checked. The exporter repeats a node's full string on every
     * edge line it appears in, which is not a duplicate declaration.
     */
    private fun assertNoDuplicateNodeIds(testDir: String, graph: List<String>) {
        val declaration = Regex("""^\s*(n\d+)\[[^]]*]:::\w+$""")
        val ids = graph.mapNotNull { declaration.find(it)?.groupValues?.get(1) }
        val duplicates = ids.groupBy { it }.filterValues { it.size > 1 }.keys
        assertTrue(duplicates.isEmpty(), "Graph for '$testDir' declares the same node id twice: $duplicates")
    }

    /** An unlabelled operator makes the graph of a calculation unreadable. */
    private fun assertNoUnknownOperators(testDir: String, graph: List<String>) {
        val unknown = graph.filter { it.contains("[UNKNOWN]") }
        assertTrue(unknown.isEmpty(), "Graph for '$testDir' has unlabelled operators: $unknown")
    }

    /**
     * Both branches of `cond ? a : b` produce the value of the expression and the condition picks
     * between them, so all three have to reach the result. Anything less silently drops a value
     * that the code really can produce: for a guarded division it hides either the guard or the
     * fallback.
     */
    @Test
    fun ternaryConnectsBothBranchesAndCondition() {
        val edges = edgeLabels(buildGraph("ternary", listOf("App.java")))
        assertTrue("==" to "ternary" in edges, "condition does not reach the selection: $edges")
        assertTrue("fallback" to "ternary" in edges, "true branch does not reach the selection: $edges")
        assertTrue("div" to "ternary" in edges, "false branch does not reach the selection: $edges")
        assertTrue("ternary" to "guarded" in edges, "selection does not reach the variable: $edges")
    }

    /**
     * A call to a method outside the analysed sources has no body to inline, so it becomes one
     * node that the arguments flow into and the result flows out of. Values still have to be
     * traceable through it.
     */
    @Test
    fun externalCallBecomesOpaqueNode() {
        val edges = edgeLabels(buildGraph("externalCall", listOf("App.java")))
        assertTrue("a" to "abs" in edges, "argument does not reach the external call: $edges")
        assertTrue("abs" to "b" in edges, "external call result does not reach the variable: $edges")
        assertTrue("b" to "println" in edges, "argument does not reach the external call: $edges")
        assertTrue("+" to "c" in edges, "flow does not continue past the external call: $edges")
    }

    /**
     * An object returned by a method outside the analysed sources has no constructor to run, so
     * nothing is known about its memory position. It still has to be usable as a receiver.
     */
    @Test
    fun externalObjectIsUsableAsReceiver() {
        val edges = edgeLabels(buildGraph("externalObject", listOf("App.java")))
        assertTrue("of" to "items" in edges, "external call result does not reach the variable: $edges")
        assertTrue("items" to "size" in edges, "receiver does not reach the call made on it: $edges")
        assertTrue("+" to "doubled" in edges, "flow does not continue past the external object: $edges")
    }

    /** The receiver of a call can be another call, so a value has to stay traceable along a chain. */
    @Test
    fun chainedCallsStayConnected() {
        val edges = edgeLabels(buildGraph("chainedCall", listOf("App.java")))
        assertTrue("items" to "stream" in edges, "receiver does not reach the first call: $edges")
        assertTrue("stream" to "toList" in edges, "first call does not reach the second: $edges")
        assertTrue("toList" to "size" in edges, "second call does not reach the third: $edges")
        assertTrue("size" to "size" in edges, "call result does not reach the variable: $edges")
    }

    /**
     * A unary operator has to become a node of its own. Returning the operand's node instead
     * makes `-value` identical to `value` and `!flag` identical to `flag`, which is not a gap in
     * the graph but a claim that the code does something it does not.
     */
    @Test
    fun unaryOperatorsAreVisibleInTheGraph() {
        val edges = edgeLabels(buildGraph("unary", listOf("App.java")))
        assertTrue("value" to "neg" in edges, "operand does not reach the negation: $edges")
        assertTrue("neg" to "negated" in edges, "negation does not reach the variable: $edges")
        assertTrue("flag" to "not" in edges, "operand does not reach the complement: $edges")
        assertTrue("not" to "inverted" in edges, "complement does not reach the variable: $edges")
        assertTrue("counter" to "postInc" in edges, "operand does not reach the increment: $edges")
    }

    /**
     * An expression codeflow does not model must fail, and must say where. A silently wrong graph
     * is worse than none, because nothing about it invites a second look.
     */
    @Test
    fun unmodelledExpressionFailsWithSourceLocation() {
        val error = assertFailsWith<GraphException> { buildGraph("unsupported", listOf("App.java")) }
        val message = error.message ?: ""
        assertTrue("LAMBDA_EXPRESSION" in message, "error does not name the construct: $message")
        assertTrue("unsupported/App.java:16" in message, "error does not give file and line: $message")
    }

    /**
     * Two methods named `twice`, one taking an int and one a String. Which body runs at a call
     * site is decided by the argument types, so a lookup by name has to pick one and be wrong at
     * half the call sites - silently, since the body it inlines is real code that reads fine.
     */
    @Test
    fun overloadsResolveToTheBodyThatRuns() {
        val edges = edgeLabels(buildGraph("overload", listOf("App.java")))
        assertTrue("number" to "value" in edges, "int argument does not reach the int parameter: $edges")
        assertTrue("value" to "*" in edges, "the int overload's body was not inlined: $edges")
        assertTrue("*" to "scaled" in edges, "the int overload's body was not inlined: $edges")
        assertTrue("\"abc\"" to "text" in edges, "String argument does not reach the String parameter: $edges")
        assertTrue("text" to "length" in edges, "the String overload's body was not inlined: $edges")
        assertTrue("length" to "counted" in edges, "the String overload's body was not inlined: $edges")
    }

    /**
     * `Account.close()` and `Connection.close()` are different methods that happen to share a name.
     * Keyed by name they were one entry, so both call sites were drawn with the same body.
     */
    @Test
    fun sameMethodNameOnTwoClassesStaysTwoMethods() {
        val edges = edgeLabels(buildGraph("sameName", listOf("App.java")))
        assertTrue("-" to "settled" in edges, "Account.close's body is missing: $edges")
        assertTrue("+" to "flushed" in edges, "Connection.close's body is missing: $edges")
        assertTrue("settled" to "close" in edges, "Account.close does not return its value: $edges")
        assertTrue("flushed" to "close" in edges, "Connection.close does not return its value: $edges")
    }

    /**
     * `total` names both an int field and a Holder local. Whether a variable holds a value or a
     * reference decides how it is modelled, and reading that off a map keyed by bare name let the
     * last declaration parsed answer for every `total` in the sources.
     */
    @Test
    fun sameNameWithTwoTypesIsModelledByType() {
        val nodes = nodeTypes(buildGraph("shadowedType", listOf("App.java")))
        assertTrue("total" to "OBJ_VARIABLE" in nodes, "the Holder local is not an object: $nodes")
        assertTrue("total" to "VARIABLE" in nodes, "the int field is not a value: $nodes")
    }

    /**
     * The tool is pointed at sources with no classpath, so most of a real file's types cannot be
     * resolved. That has to degrade to the opaque external node, not to a failure and not to a
     * guess - this is the guard on codeflow still working on the input it exists for.
     */
    @Test
    fun unresolvableTypeStaysOpaqueAndTraceable() {
        val edges = edgeLabels(buildGraph("unresolvedType", listOf("App.java")))
        assertTrue("size" to "create" in edges, "argument does not reach the unresolvable call: $edges")
        assertTrue("create" to "widget" in edges, "call result does not reach the variable: $edges")
        assertTrue("widget" to "measure" in edges, "receiver does not reach the call made on it: $edges")
        assertTrue("+" to "total" in edges, "flow does not continue past the unresolvable type: $edges")
    }

    /**
     * outer() and inner() each declare a local `amount` on the same instance. They are two
     * variables, and the value read back in outer() is the one outer() assigned.
     *
     * Keyed by name and instance they were one, and both were filed on the same MemPos under that
     * one key, so the callee's assignment overwrote the caller's and outer() read inner()'s value.
     * The labels cannot tell the two apart, which is the point: on the diagram this was invisible.
     */
    @Test
    fun localsOfTheSameNameInTwoMethodsStayApart() {
        val graph = buildGraph("collidingLocals", listOf("App.java"))
        assertTrue(reaches(graph, "1", "afterwards"), "outer's own value does not reach it: $graph")
        assertTrue(!reaches(graph, "2", "afterwards"), "the callee's value leaked into the caller: $graph")
        assertTrue(reaches(graph, "2", "consumed"), "inner's value does not reach its own read: $graph")
    }

    /**
     * The method boundary is what a viewer draws as a rectangle, so a call has to come out as a
     * node nested inside its caller's node - that containment *is* the boundary in GraphML, there
     * is no separate notion of a group. Flat output would still render, as a correct graph with
     * every method boundary silently gone.
     */
    @Test
    fun graphmlNestsACallInsideItsCaller() {
        val doc = buildGraphml("funcCall", listOf("App.java"))
        val blocks = elements(doc, "node").filter { dataOf(it, "type") == "METHOD" }
        val methodC = blocks.filter { labelOf(it) == "methodC" }
        assertEquals(2, methodC.size, "methodC is inlined at two call sites and should appear twice")
        assertTrue(methodC.all { enclosingBlockLabel(it) == "methodB" }, "methodC is not nested in methodB")

        val methodB = blocks.single { labelOf(it) == "methodB" }
        assertEquals("main", enclosingBlockLabel(methodB), "methodB is not nested in main")

        val paramH = elements(doc, "node").filter { labelOf(it) == "paramH" }
        assertTrue(paramH.isNotEmpty(), "methodC's parameter is missing")
        assertTrue(paramH.all { enclosingBlockLabel(it) == "methodC" }, "a node escaped its own method")
    }

    /**
     * `<init>`, `<`, `>` and a quoted literal are all real labels, and all of them are XML syntax.
     * Written raw they produce a document a viewer refuses to open, or worse, one it opens with the
     * label truncated at the first bad character.
     */
    @Test
    fun graphmlEscapesLabelsThatAreXmlSyntax() {
        val constructor = elements(buildGraphml("constructor", listOf("App.java")), "node").map { labelOf(it) }
        assertTrue("<init>" in constructor, "the constructor's return label did not survive: $constructor")
        assertTrue("\"test\"" in constructor, "the string literal's label did not survive: $constructor")

        val operators = elements(buildGraphml("operators", listOf("App.java")), "node").map { labelOf(it) }
        assertTrue("<" in operators, "the less-than operator did not survive: $operators")
        assertTrue(">=" in operators, "the greater-or-equal operator did not survive: $operators")
    }

    /**
     * The two exporters render one graph, so they have to agree on it. The risk is specific: an
     * edge can cross a method boundary - a return flows to the variable in the caller - and GraphML
     * requires such an edge to be declared in a graph enclosing both ends, unlike Mermaid, which
     * takes it anywhere. Getting that wrong drops exactly the edges that join methods together.
     */
    @Test
    fun graphmlKeepsEveryEdgeTheMermaidGraphHas() {
        val mermaid = edgeLabels(buildGraph("funcCall", listOf("App.java"))).sortedBy { it.toString() }
        val graphml = graphmlEdgeLabels(buildGraphml("funcCall", listOf("App.java"))).sortedBy { it.toString() }
        assertEquals(mermaid, graphml, "the two renderings of one graph disagree on its edges")
    }

    /**
     * `parent` is what Cytoscape draws as a containing box, so it is the method boundary and
     * nothing else carries it. A payload with the nesting flattened renders as a correct graph
     * with every boundary silently gone.
     */
    @Test
    fun jsonNestsACallInsideItsCaller() {
        val doc = buildJson("funcCall", listOf("App.java"))
        val nodes = jsonNodes(doc)
        val byId = nodes.associateBy { it.get("id").asString }

        val root = nodes.single { jsonParent(it) == null }
        assertEquals("main", jsonLabel(root), "the parentless node should be the outermost method")

        val methodC = nodes.filter { jsonLabel(it) == "methodC" && it.get("type").asString == "METHOD" }
        assertEquals(2, methodC.size, "methodC is inlined at two call sites and should appear twice")
        assertTrue(
            methodC.all { jsonLabel(byId.getValue(jsonParent(it)!!)) == "methodB" },
            "methodC is not nested in methodB"
        )

        val paramH = nodes.filter { jsonLabel(it) == "paramH" }
        assertTrue(paramH.isNotEmpty(), "methodC's parameter is missing")
        assertTrue(
            paramH.all { jsonLabel(byId.getValue(jsonParent(it)!!)) == "methodC" },
            "a node escaped its own method"
        )
    }

    /**
     * A label carrying a quote ends the JSON string early and the rest of the payload becomes
     * syntax errors, so the page renders nothing at all.
     */
    @Test
    fun jsonEscapesLabelsThatAreJsonSyntax() {
        val labels = jsonNodes(buildJson("constructor", listOf("App.java"))).map { jsonLabel(it) }
        assertTrue("\"test\"" in labels, "the string literal's label did not survive: $labels")
        assertTrue("<init>" in labels, "the constructor's return label did not survive: $labels")
    }

    /** The three exporters render one graph, so they have to agree on its edges. */
    @Test
    fun jsonKeepsEveryEdgeTheMermaidGraphHas() {
        val mermaid = edgeLabels(buildGraph("funcCall", listOf("App.java"))).sortedBy { it.toString() }
        val json = jsonEdgeLabels(buildJson("funcCall", listOf("App.java"))).sortedBy { it.toString() }
        assertEquals(mermaid, json, "the two renderings of one graph disagree on its edges")
    }

    /**
     * The page has to carry its own libraries. A viewer that renders nothing because an asset was
     * missing looks exactly like a graph with no nodes, so the export fails loudly instead.
     */
    @Test
    fun htmlPageCarriesItsLibrariesAndItsData() {
        val page = StringBuilder()
        val testDirPath = testResourcesPath.resolve("funcCall")
        val mainMethod = AstReader(testResourcesPath).process(listOf(testDirPath.resolve("App.java")))
        HtmlExporter().processMainMethod(mainMethod) { page.append(it).append("\n") }
        val html = page.toString()

        // Strings from inside the bundles themselves. "cytoscape" and "ELK" both occur in our own
        // viewer.mjs, so asserting on those passed with not one library present.
        assertTrue("The Cytoscape Consortium" in html, "the renderer was not inlined")
        assertTrue("org.eclipse.elk" in html, "the layout engine was not inlined")
        assertTrue("REVEAL_DEPTH" in html, "our own viewer code was not inlined")
        assertTrue("\"label\": \"methodC\"" in html, "the graph payload was not inlined")
        assertTrue("<script" in html && "</html>" in html, "the page is not a complete document")
    }

